import unittest

from spacefractions.admin.service import AdminService
from spacefractions.persistence import connect, init_db
from spacefractions.question.repository import QuestionRepository
from spacefractions.question.service import QuestionService


class AdminServiceTest(unittest.TestCase):
    def setUp(self):
        self.conn = connect(":memory:")
        init_db(self.conn)
        self.questions = QuestionService(QuestionRepository(self.conn))
        self.admin = AdminService(self.questions)

    def tearDown(self):
        self.conn.close()

    def test_add_question(self):
        question = self.admin.add_question("1/4 + 1/4", ["1/4", "1/2"], 1)
        self.assertIsNotNone(question.id)
        self.assertEqual(self.questions.get_prompt(question.id), "1/4 + 1/4")

    def test_update_questions(self):
        q1 = self.questions.add_question("old1", ["a"], 0)
        q2 = self.questions.add_question("old2", ["b"], 0)
        q1.prompt = "new1"
        q2.prompt = "new2"
        self.admin.update_questions([q1, q2])
        self.assertEqual(self.questions.get_prompt(q1.id), "new1")
        self.assertEqual(self.questions.get_prompt(q2.id), "new2")


if __name__ == "__main__":
    unittest.main()
